    { "theme": "Calculando a área de triângulos e quadriláteros", "curriculumCode": "EF07MA31", "description": "Estabelecimento de expressões de cálculo de área de triângulos e de quadriláteros a partir da decomposição e comparação de figuras.", "materials": ["Papel quadriculado", "Tesoura", "Régua", "Figuras planas recortadas"], "steps": ["Apresentar um retângulo e discutir como calcular sua área.", "Cortar o retângulo ao meio na diagonal para obter dois triângulos.", "Relacionar a área do triângulo com a metade da área do retângulo correspondente.", "Repetir o processo para outros quadriláteros, como o paralelogramo.", "Propor que os alunos calculem a área de novas figuras usando as expressões descobertas.", "Registrar as expressões de cálculo de área encontradas para cada figura."] },
    { "theme": "Área de figuras compostas: decompondo em triângulos e retângulos", "curriculumCode": "EF07MA32", "description": "Resolução e elaboração de situações-problema de cálculo de área de figuras planas que podem ser decompostas em quadrados, retângulos e/ou triângulos, utilizando a equivalência entre áreas.", "materials": ["Papel quadriculado", "Tesoura", "Figuras planas irregulares recortadas", "Régua"], "steps": ["Apresentar uma figura plana irregular composta por partes reconhecíveis.", "Demonstrar como decompor a figura em quadrados, retângulos e triângulos.", "Calcular a área de cada parte separadamente.", "Somar as áreas parciais para obter a área total da figura.", "Propor que os alunos decomponham e calculem a área de uma nova figura em duplas.", "Discutir a ideia de equivalência entre áreas de figuras diferentes."] },
    { "theme": "Descobrindo o número pi (π)", "curriculumCode": "EF07MA33", "description": "Estabelecimento do número π como a razão entre a medida de uma circunferência e seu diâmetro, para compreender e resolver problemas, inclusive de natureza histórica.", "materials": ["Objetos circulares variados (tampas, pratos, rodas)", "Barbante", "Fita métrica", "Calculadora"], "steps": ["Medir a circunferência e o diâmetro de diferentes objetos circulares usando barbante e fita métrica.", "Calcular a razão entre a medida da circunferência e o diâmetro para cada objeto.", "Comparar os resultados obtidos pelos diferentes grupos.", "Discutir como esses resultados se aproximam do número π.", "Apresentar brevemente a história da descoberta do número π.", "Aplicar o valor de π para resolver um problema envolvendo comprimento de circunferência."] },
    { "theme": "Experimentos aleatórios e estimativa de probabilidade", "curriculumCode": "EF07MA34", "description": "Planejamento e realização de experimentos aleatórios ou simulações que envolvem cálculo de probabilidades ou estimativas por meio da frequência de ocorrências.", "materials": ["Dados", "Moedas", "Saquinho com fichas coloridas", "Folha de registro de frequências"], "steps": ["Planejar em grupo um experimento aleatório, como lançar um dado várias vezes.", "Definir o espaço amostral do experimento antes de realizá-lo.", "Realizar o experimento repetidas vezes, registrando os resultados obtidos.", "Calcular a frequência de cada resultado e estimar a probabilidade a partir dela.", "Comparar as estimativas obtidas pelos diferentes grupos.", "Discutir como o número de repetições influencia a estimativa."] },
    { "theme": "Média e amplitude: interpretando dados de uma pesquisa", "curriculumCode": "EF07MA35", "description": "Compreensão, em contextos significativos, do significado de média estatística como indicador de tendência de uma pesquisa, com cálculo do valor e relação com a amplitude do conjunto de dados.", "materials": ["Conjunto de dados de uma pesquisa simples (alturas, notas, idades)", "Calculadora", "Folha de registro"], "steps": ["Coletar um pequeno conjunto de dados da própria turma, como idade ou altura.", "Calcular coletivamente a média do conjunto de dados.", "Identificar o maior e o menor valor para calcular a amplitude.", "Discutir o que a média representa como indicador da tendência do grupo.", "Relacionar intuitivamente a amplitude com a variação dos dados.", "Propor que os alunos calculem média e amplitude de um novo conjunto de dados."] },
    { "theme": "Planejando uma pesquisa: amostra ou censo?", "curriculumCode": "EF07MA36", "description": "Planejamento e realização de pesquisa envolvendo um tema da realidade social, identificando a necessidade de ser censitária ou de usar amostra, com interpretação e comunicação dos dados por relatório, tabelas e gráficos.", "materials": ["Computador ou tablet com planilha eletrônica", "Formulário de pesquisa", "Projetor (opcional)"], "steps": ["Escolher coletivamente um tema social relevante para a pesquisa.", "Discutir se é necessário pesquisar todos (censo) ou uma parte (amostra) do grupo.", "Elaborar as perguntas do formulário de pesquisa em grupo.", "Coletar os dados e registrá-los em uma planilha eletrônica.", "Construir tabelas e gráficos a partir dos dados coletados.", "Redigir um relatório curto interpretando os resultados encontrados."] },
    { "theme": "Lendo gráficos de setores na mídia", "curriculumCode": "EF07MA37", "description": "Leitura, interpretação e análise de dados apresentados em gráficos de setores divulgados pela mídia, compreendendo quando é possível ou conveniente sua utilização.", "materials": ["Reportagens com gráficos de setores impressos", "Compasso e transferidor (para construção)", "Folha de análise"], "steps": ["Selecionar uma reportagem que apresente um gráfico de setores.", "Ler coletivamente os dados representados no gráfico.", "Discutir o que cada setor representa em relação ao total.", "Comparar o gráfico de setores com outro tipo de gráfico para o mesmo dado.", "Propor que os alunos construam um gráfico de setores simples a partir de dados da turma.", "Responder a perguntas de interpretação sobre o gráfico produzido."] }
