    { "theme": "As primeiras fases da globalização no cotidiano", "curriculumCode": "EF07GE19*", "description": "Aula que aplica conhecimentos geográficos para identificar fenômenos socioespaciais representativos das primeiras fases da globalização em diferentes lugares.", "materials": ["Imagens de produtos e rotas comerciais históricas", "Mapa de rotas comerciais antigas", "Quadro branco"], "steps": ["Apresentar o conceito de globalização e suas fases iniciais.", "Mostrar exemplos de produtos e trocas comerciais que conectavam regiões distantes historicamente.", "Formar grupos para mapear uma rota comercial antiga e seus impactos locais.", "Relacionar os exemplos históricos com fenômenos de conexão global observados hoje.", "Encerrar com discussão sobre continuidades entre globalização antiga e atual."] },
    { "theme": "Recursos naturais, produção e impactos socioambientais", "curriculumCode": "EF07GE06", "description": "Aula que discute como diferentes sociedades se apropriam dos recursos naturais e como os processos produtivos geram impactos socioambientais e influenciam trabalho e riqueza.", "materials": ["Estudo de caso de uma cadeia produtiva (ex: mineração, agricultura)", "Mapa de distribuição de recursos naturais no Brasil", "Quadro branco"], "steps": ["Apresentar um exemplo de cadeia produtiva que utiliza recursos naturais brasileiros.", "Formar grupos para mapear as etapas da produção até o consumo.", "Pedir que identifiquem impactos socioambientais em cada etapa.", "Discutir coletivamente como esses processos afetam trabalho e distribuição de riqueza.", "Fechar com proposta de alternativas mais sustentáveis para a cadeia estudada."] },
    { "theme": "O que é desenvolvimento sustentável?", "curriculumCode": "EF07GE20*", "description": "Aula que explica o conceito de desenvolvimento sustentável e seus indicadores econômicos, sociais, ambientais e políticos, discutindo vantagens e desvantagens em diferentes contextos.", "materials": ["Textos ou infográficos sobre desenvolvimento sustentável", "Quadro branco", "Cartolina para mural de indicadores"], "steps": ["Introduzir o conceito de desenvolvimento sustentável com exemplos do cotidiano.", "Apresentar os principais indicadores usados para medi-lo.", "Formar grupos para analisar um caso real de projeto sustentável ou não sustentável.", "Debater vantagens e desvantagens identificadas em cada caso.", "Montar um mural coletivo com os indicadores discutidos."] },
    { "theme": "Consumo consciente e sociedades sustentáveis", "curriculumCode": "EF07GE21*", "description": "Aula que relaciona processos produtivos sustentáveis com práticas de consumo consciente e responsável, discutindo caminhos para sociedades mais sustentáveis.", "materials": ["Exemplos de rótulos e selos de produtos sustentáveis", "Cartazes ou folhetos sobre consumo consciente", "Quadro branco"], "steps": ["Retomar o conceito de desenvolvimento sustentável estudado anteriormente.", "Apresentar exemplos de produção sustentável e de consumo consciente.", "Formar grupos para analisar hábitos de consumo da própria turma.", "Propor que cada grupo sugira uma mudança de hábito viável para reduzir impacto ambiental.", "Fechar com compromisso coletivo de pequenas ações sustentáveis."] },
    { "theme": "Redes de transporte e comunicação em escala global", "curriculumCode": "EF07GE07A", "description": "Aula que analisa o papel das redes de transporte e comunicação na circulação de mercadorias, pessoas e informações em escala global.", "materials": ["Mapa de rotas de transporte global (marítimas, aéreas)", "Dados sobre uso de internet e comunicação global", "Quadro branco"], "steps": ["Apresentar exemplos de redes de transporte que conectam o mundo.", "Mostrar dados sobre redes de comunicação digital e seu alcance global.", "Formar grupos para traçar o caminho de um produto até o consumidor final.", "Relacionar esse caminho com fluxos materiais e imateriais discutidos em aula.", "Encerrar com discussão sobre desigualdades de acesso a essas redes."] },
    { "theme": "Redes de transporte e o território brasileiro", "curriculumCode": "EF07GE07B", "description": "Aula que categoriza redes de transporte e comunicação e analisa sua influência nos processos produtivos e na configuração do território brasileiro.", "materials": ["Mapa de malha rodoviária, ferroviária e portuária do Brasil", "Quadro branco", "Post-its"], "steps": ["Apresentar os principais tipos de redes de transporte presentes no Brasil.", "Formar grupos para classificar essas redes por tipo e função.", "Pedir que identifiquem regiões bem e mal conectadas por essas redes.", "Discutir como essa configuração influencia a produção e a economia regional.", "Fechar com proposta de melhoria de conectividade para uma região escolhida."] },
    { "theme": "Industrialização e inovação tecnológica no Brasil", "curriculumCode": "EF07GE08", "description": "Aula que estabelece relações entre industrialização e inovação tecnológica, analisando transformações socioeconômicas, políticas, culturais e ambientais no território brasileiro.", "materials": ["Linha do tempo da industrialização brasileira", "Mapa de polos industriais do Brasil", "Quadro branco"], "steps": ["Apresentar as fases da industrialização brasileira e sua relação com inovações tecnológicas.", "Formar grupos para pesquisar um polo industrial brasileiro específico.", "Pedir que identifiquem transformações sociais, econômicas e ambientais associadas.", "Compartilhar descobertas em apresentação rápida.", "Encerrar com debate sobre o papel da tecnologia na indústria atual."] },
    { "theme": "Espaços industriais-tecnológicos em São Paulo", "curriculumCode": "EF07GE22*", "description": "Aula que caracteriza espaços industriais-tecnológicos e discute o papel de políticas governamentais na criação e expansão de centros tecnológicos, com destaque para São Paulo.", "materials": ["Mapa de polos tecnológicos do Estado de São Paulo", "Notícias sobre políticas de incentivo tecnológico", "Quadro branco"], "steps": ["Apresentar exemplos de espaços industriais-tecnológicos existentes em São Paulo.", "Formar grupos para pesquisar uma política pública de incentivo à tecnologia ou pesquisa.", "Pedir que relacionem essa política com a criação ou expansão de um centro tecnológico.", "Promover discussão sobre benefícios e desigualdades regionais geradas por esses investimentos.", "Fechar com produção de um resumo visual sobre o polo estudado."] },
    { "theme": "Construindo mapas temáticos do Brasil", "curriculumCode": "EF07GE09A", "description": "Aula prática de interpretação e elaboração de mapas temáticos com base em informações históricas, demográficas, sociais e econômicas do território brasileiro.", "materials": ["Mapa mudo do Brasil (contorno dos estados)", "Dados demográficos e econômicos simplificados", "Lápis de cor", "Legenda modelo"], "steps": ["Explicar o que é um mapa temático e como ele representa dados específicos.", "Apresentar um conjunto de dados por estado ou região.", "Pedir que os alunos criem uma legenda de cores para representar os dados.", "Orientar a coloração do mapa mudo conforme a legenda criada.", "Encerrar com apresentação e leitura coletiva dos mapas produzidos."] },
    { "theme": "Tecnologias digitais para identificar padrões espaciais", "curriculumCode": "EF07GE09B", "description": "Aula que aplica tecnologias digitais simples para identificar padrões espaciais, regionalizações e semelhanças territoriais no Brasil, com foco em São Paulo.", "materials": ["Computador ou celular com acesso a mapas digitais/GPS", "Projetor", "Roteiro de exploração impresso"], "steps": ["Apresentar uma ferramenta digital de mapas e suas funções básicas.", "Demonstrar como identificar camadas de informação.", "Orientar os alunos, em duplas, a explorarem uma região do Estado de São Paulo usando a ferramenta.", "Pedir que registrem padrões espaciais observados.", "Fechar com socialização das descobertas de cada dupla."] },
    { "theme": "Comparando regiões brasileiras por indicadores socioeconômicos", "curriculumCode": "EF07GE10", "description": "Aula que identifica indicadores socioeconômicos, elabora representações gráficas e compara as regiões brasileiras ao longo do tempo.", "materials": ["Tabelas de indicadores socioeconômicos por região", "Papel quadriculado ou planilha simples", "Réguas"], "steps": ["Apresentar indicadores socioeconômicos comuns por região.", "Formar grupos, cada um responsável por uma região brasileira.", "Orientar a construção de um gráfico simples com os dados da região.", "Comparar os gráficos das diferentes regiões em um mural conjunto.", "Discutir coletivamente as desigualdades regionais reveladas pelos gráficos."] },
    { "theme": "Domínios morfoclimáticos do Brasil", "curriculumCode": "EF07GE11", "description": "Aula que identifica os domínios morfoclimáticos brasileiros e relaciona relevo, clima, vegetação e hidrografia como componentes físico-naturais integrados.", "materials": ["Mapa de domínios morfoclimáticos do Brasil", "Imagens representativas de cada domínio", "Quadro branco"], "steps": ["Apresentar o conceito de domínio morfoclimático e seus componentes.", "Mostrar o mapa com os principais domínios do território brasileiro.", "Formar grupos para estudar um domínio específico e suas características físicas.", "Pedir que relacionem clima, relevo e vegetação do domínio estudado.", "Encerrar com apresentação comparativa entre os domínios estudados."] },
    { "theme": "Recursos naturais e biodiversidade nos biomas brasileiros", "curriculumCode": "EF07GE23*", "description": "Aula que avalia a importância da distribuição de recursos naturais e da biodiversidade nos diversos biomas brasileiros.", "materials": ["Mapa de biomas do Brasil", "Fichas com espécies representativas de cada bioma", "Quadro branco"], "steps": ["Apresentar o mapa de biomas brasileiros e sua distribuição de recursos naturais.", "Formar grupos, cada um representando um bioma.", "Pedir que pesquisem recursos naturais e espécies características do bioma escolhido.", "Discutir a importância desses recursos para as comunidades locais e para o país.", "Fechar com apresentação ilustrada de cada bioma pelos grupos."] },
    { "theme": "Semelhanças e diferenças entre os biomas brasileiros", "curriculumCode": "EF07GE24*", "description": "Aula que identifica generalidades e singularidades dos biomas brasileiros, com destaque para os biomas presentes no Estado de São Paulo.", "materials": ["Mapa de biomas do Brasil e do Estado de São Paulo", "Imagens comparativas de biomas", "Tabela comparativa impressa"], "steps": ["Retomar os biomas brasileiros estudados na aula anterior.", "Apresentar imagens comparando características gerais e específicas de cada bioma.", "Formar grupos para preencher uma tabela comparando dois biomas, incluindo os presentes em São Paulo.", "Discutir semelhanças e diferenças identificadas pelos grupos.", "Encerrar com síntese coletiva sobre a singularidade dos biomas paulistas."] },
    { "theme": "Preservação e conservação dos biomas brasileiros", "curriculumCode": "EF07GE25*", "description": "Aula que analisa problemáticas socioambientais dos biomas brasileiros e discute ações de preservação e conservação, com destaque para o Estado de São Paulo.", "materials": ["Notícias sobre desmatamento ou queimadas em biomas brasileiros", "Mapa de áreas de preservação de São Paulo", "Cartolina para plano de ação"], "steps": ["Apresentar problemáticas socioambientais atuais em diferentes biomas brasileiros.", "Formar grupos para pesquisar uma ameaça específica em um bioma.", "Pedir que identifiquem ações de preservação já existentes para esse problema.", "Propor que cada grupo elabore uma pequena campanha de conscientização.", "Fechar com apresentação das campanhas à turma."] },
    { "theme": "Sistema Nacional de Unidades de Conservação (SNUC)", "curriculumCode": "EF07GE12", "description": "Aula que descreve a organização do SNUC, compara tipos de Unidades de Conservação e discute práticas de conservação e preservação da biodiversidade nas regiões brasileiras.", "materials": ["Mapa de Unidades de Conservação do Brasil", "Ficha explicativa dos tipos de UC (proteção integral e uso sustentável)", "Quadro branco"], "steps": ["Explicar o que é o SNUC e por que ele foi criado.", "Apresentar os dois grandes grupos de Unidades de Conservação e suas diferenças.", "Formar grupos para pesquisar uma Unidade de Conservação brasileira específica.", "Pedir que identifiquem o tipo de UC e suas práticas de manejo.", "Encerrar com comparação entre as UCs pesquisadas pelos grupos."] },
    { "theme": "Territórios quilombolas, terras indígenas e reservas extrativistas", "curriculumCode": "EF07GE26*", "description": "Aula que identifica territórios quilombolas, terras indígenas e reservas extrativistas dentro das Unidades de Conservação, discutindo seu papel na proteção ambiental e os conflitos de resistência envolvidos.", "materials": ["Mapa de territórios quilombolas e terras indígenas em São Paulo", "Notícias sobre conflitos territoriais", "Quadro branco"], "steps": ["Apresentar os conceitos de território quilombola, terra indígena e reserva extrativista.", "Mostrar no mapa exemplos localizados no Estado de São Paulo.", "Formar grupos para pesquisar o papel desses grupos na conservação ambiental.", "Discutir um caso de conflito ou resistência territorial relacionado ao tema.", "Fechar com roda de conversa sobre a importância do reconhecimento desses territórios."] },
    { "theme": "Políticas públicas e gestão do patrimônio ambiental", "curriculumCode": "EF07GE27*", "description": "Aula que analisa a atuação de instituições públicas e da sociedade civil na formulação de políticas socioambientais, identificando instrumentos de gestão territorial ambiental no Brasil e em São Paulo.", "materials": ["Exemplos de políticas públicas ambientais (leis, planos de manejo)", "Notícias sobre atuação de ONGs ambientais", "Quadro branco"], "steps": ["Apresentar exemplos de instituições públicas responsáveis pela gestão ambiental no Brasil e em São Paulo.", "Mostrar exemplos de atuação da sociedade civil organizada na área ambiental.", "Formar grupos para pesquisar um instrumento de gestão territorial ambiental.", "Pedir que expliquem como esse instrumento protege o patrimônio ambiental.", "Encerrar com debate sobre a importância da parceria entre poder público e sociedade civil."] }
